function performChunk(datas,taskHandler){
	if(datas.length===0){
		return;
	}
	let i=0;
	_run();

	function _run(){
		if(i>=datas.length){
			return
		}
		requestIdleCallback((idle)=>{
			while(idle.timeRemaining()>0 && i<datas.length){
				taskHandler(datas,i);
				i++
			}
			_run()
		})
	}
}

